package com.portfolio.features.social.controller; import com.portfolio.common.api.ApiResponse; import com.portfolio.features.social.dto.*; import com.portfolio.features.social.mapper.SocialLinkMapper; import com.portfolio.features.social.service.SocialLinkService; import com.portfolio.features.user.service.UserService; import jakarta.validation.Valid; import java.util.*; import lombok.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/social-links") @RequiredArgsConstructor public class SocialLinkController {private final SocialLinkService service;private final UserService users;private final SocialLinkMapper mapper;@GetMapping public ApiResponse<List<SocialLinkResponse>> list(@AuthenticationPrincipal Jwt j){return ApiResponse.success("Social links retrieved successfully.",service.list(users.synchronize(j)).stream().map(mapper::toResponse).toList());}@PostMapping public ApiResponse<SocialLinkResponse> create(@AuthenticationPrincipal Jwt j,@Valid @RequestBody SocialLinkRequest r){return ApiResponse.success("Social link created successfully.",mapper.toResponse(service.create(users.synchronize(j),r)));}@PutMapping("/{id}") public ApiResponse<SocialLinkResponse> update(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody SocialLinkRequest r){return ApiResponse.success("Social link updated successfully.",mapper.toResponse(service.update(users.synchronize(j),id,r)));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){service.delete(users.synchronize(j),id);return ApiResponse.success("Social link deleted successfully.",null);}}
